class Solution:
    def topo_sort(self, n: int, edges: list[list[int]]) -> list[int]:
        adj = {i: [] for i in range(n)}
        for u, v in edges:
            adj[u].append(v)

        visited = [0] * n # 0: unvisited, 1: visiting, 2: visited
        order = []

        def dfs(node):
            if visited[node] == 1:
                return False
            if visited[node] == 2:
                return True

            visited[node] = 1
            for neighbor in adj[node]:
                if not dfs(neighbor):
                    return False
            visited[node] = 2
            order.append(node)
            return True

        for i in range(n):
            if visited[i] == 0:
                if not dfs(i):
                    return []

        return order[::-1]

