class Solution:
    def kruskals(self, n: int, edges: list[list[int]]) -> int:
        parent = list(range(n))
        rank = [0] * n

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                if rank[root_i] < rank[root_j]:
                    parent[root_i] = root_j
                elif rank[root_i] > rank[root_j]:
                    parent[root_j] = root_i
                else:
                    parent[root_j] = root_i
                    rank[root_i] += 1
                return True
            return False

        edges.sort(key=lambda x: x[2])
        total_weight = 0
        edges_used = 0

        for u, v, w in edges:
            if union(u, v):
                total_weight += w
                edges_used += 1
                if edges_used == n - 1:
                    break

        return total_weight if edges_used == n - 1 and n > 0 else (0 if n == 1 else -1)

